	tout[v] = timer[0]
	timer[0] += 1
	yield 0

def is_ancestor(u, v):
	return tin[u] <= tin[v] and tout[u] >= tout[v]

def lca(u, v):
	if is_ancestor(u, v):
		return u
	if is_ancestor(v, u):
		return v
	for i in range(L - 1, -1, -1):
		if not is_ancestor(up[u][i], v):
			u = up[u][i]
	return up[u][0]

def cal_node(u, step):
	for i in range(L - 1, -1, -1):
		if pows[i] > step:
			continue
		u = up[u][i]
		step -= pows[i]
	return u
